// Custom sampler stubs (mapped to noise texture)
#define sampler_smalltiled_lizard_scales sampler_noise_lq
#define sat clamp01
sampler sampler_smalltiled_lizard_scales;
vec4 texsize_smalltiled_lizard_scales;
vec2 dz1, uv0, uv1,uv2,uv3;
float li, radi;
const float anz = 20;
const vec2 pix = (vec2(1.0)/uTexSize) * 2.0;
const vec2 moonpos = .5;
float GetBuf(vec2 uvi)
{float res;
res = mix(GetBlur1(uvi).r,GetBlur1(uvi).g,0.5)-.5;
res = pow(res, 2.0 )*sign(res);
return res;}
//Untergrund
uv2=uv*uTexSize.xy*texsize_smalltiled_lizard_scales.zw / 4.0+rand_preset.xy;
vec3 bk= texture(sampler_smalltiled_lizard_scales,uv2 +dz1)  *0.5;
ret = bk;
ret -= shine.b*0.75;
ret = sat(ret+ 1.3*GetPixel(uv).b);
//float glow =  GetBlur3(uv).b* tex3D(sampler_noisevol_hq,vec3(uv / 2.0,uTime / 8.0)).r*q10;
//ret+=glow*vec3( 1.0 ,0.7, 2.0 )*.3;
uv3=(uv-0.5)*uAspect.xy;
uv2=uv3-vec2(q1,-q2);
li = 0.03/pow(length(uv2), 1.0 );
ret+= li*(.4+bk)*audioHighSmooth;
uv2.x=uv3.x-mix(q1,-q1,q5);
uv2.y=uv3.y-mix(-q2,q2,q6);
li = 0.03/pow(length(uv2), 1.0 );
ret+= li*(1.0 - bk)*audioHighSmooth*(q7>0.3);
//ret = GetPixel(uv);
}
//Martin

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  uv0 = uv;
//uv mit Wasseroberflaeche modulieren
dz1.x = GetBuf(uv+pix*vec2( 1.0 , 0.0 )) - GetBuf(uv+pix*vec2(-1, 0.0 ));
dz1.y = GetBuf(uv+pix*vec2( 0.0 , 1.0 )) - GetBuf(uv+pix*vec2( 0.0 ,-1));
uv += dz1 * clamp01(1.0 - GetBuf(uv0))*.4;
vec3 shine = 0; radi = 1;
for (int n=1; n <= anz;  n++)
{
vec2 uv2= (uv-moonpos)*radi+moonpos;
shine.b= max (shine.b, GetBlur1(uv2).b*(1-1.0*n/anz));
radi += .5/anz;
  fragColor = vec4(ret, 1.0);
}

